  p11.rubric[0] = "ستون «پله» یکنواخت پایین می‌رود (زیرشاخه ← شاخه ← محل اتصال ← تنه ← ریشه) بدون پرش بیش از یک گزینه، و ردیف اول نزدیک‌ترین پله به میوه است.";
  p11.rubric[7] = "بذر در یک یا دو جمله نوشته شده و دست‌کم یک «کاشت در زمین دیگر» با اولین شاخه مشخصش آمده است.";

  /* ---------- مسیر یکپارچه (۱۱ گام) ---------- */
  var PL = {}; C.PIPELINE.forEach(function (s) { PL[s.k] = s; });
  PL.S1.core = [33, 32, 24];
  PL.S2.refs = ["P8"];
  PL.S3.core = [41];
  PL.S4.core = [2, 44, 45, 15, 1, 5];
  PL.S4.how = "در «بیان دیگر»: تجزیه میوه به اجزا، تلاش خام، فرود پله‌به‌پله با چالش/نیاز/دغدغه هر پله و پرسش چرایی هر پله، کنار زدن فرض‌های قراردادی، عناصر ریشه‌ای، تنه و ریشه.";
  PL.S5.core = [4, 7, 8, 6]; PL.S5.refs = ["FARM", "ATLAS", "P6"];
  PL.S7.core = [17, 16, 19];
  PL.S8.refs = ["P11", "P7", "P5"]; PL.S8.core = [28, 26, 27, 41];
  PL.S9.core = [21, 22, 24, 25, 39]; PL.S9.refs = ["P11", "P9"];
  PL.S10.refs = ["P3", "P4"];
  C.PIPELINE.push({ k: "S11", ph: 8, fa: "جاری کردن در زندگی", how: "در قرائت‌های روزانه بعدی، این مفهوم را به‌عنوان عینک روی رخدادهای واقعی (ترید، بانک، فیلم) به کار ببر و یک بار آن را در بازی کارآگاهی یا شبیه‌ساز تولید کن.", core: [19, 23], refs: ["P2", "P5"] });
  C.PHASE_REFS[6] = ["P11", "P5"]; C.PHASE_REFS[8] = ["P3", "P4", "P2"];

  /* ---------- مزرعه: لایه برگ، ریشه و خاک، اتصال‌های خودکار ---------- */
  C.FLAYERS.splice(5, 0, { k: "leaf", fa: "برگ (مشاهده و کاربرد زیسته)", def: "تماس درخت با جهان: یک مشاهده، رخداد یا کاربرد واقعی که از پشت این علم دیده شده (مثلاً ثبت‌های قرائت روز). برگ نور می‌گیرد: داده واقعی که درخت از آن تغذیه می‌کند.", ex: "«امروز در ترید X، تأخیر حلقه بازخورد را دیدم»" });
  C.FLAYER = {}; C.FLAYERS.forEach(function (l, i) { l.i = i; C.FLAYER[l.k] = l; });
  C.FLAYER.root.def = "نیاز بنیادینی که این علم برای پاسخ به آن پدید آمد، روشی که با آن دانسته‌هایش را می‌سنجد (برهان، آزمایش، مشاهده، مدل)، پیش‌فرض‌های بنیادینش، و به تعبیر شما «ریشه‌ها و عناصر اصلی که برای هر کس مفهوم است». «شرط دوام و پویایی» علم.";
  C.FLAYER.trunk.def = "قواعدی که همه شاخه‌های این علم به آن وابسته‌اند. «متقن» به معنای پرآزموده‌ترین و محافظت‌شده‌ترین بخش علم، نه «خلل‌ناپذیر»: تنه هم گاهی جایگزین می‌شود.";
  C.FLAYER.knot.def += " گره با ریزتر شدن به زیرگره‌ها و جوانه‌ها باز می‌شود.";
