  concerns: ["c6","c8","c12","c11"],
  src: "PDF ص ۲۰ · docx فصل ۷ ردیف ۱۷",
  fix: "مثال PDF که «منظومه شمسی و یک اتم از یک اصل پیروی می‌کنند: یک نیروی مرکزی که ساختارهای مداری ایجاد می‌کند» از نظر علمی منسوخ است: مدل سیاره‌ای یک قیاس ساختاری واقعی بود (هر دو نیرو مرکزی و عکس مجذوری‌اند و در سطح کلاسیک نگاشت برقرار است)، اما فراتر از مرز اعتبارش تعمیم داده شد: الکترون شتاب‌دار باید تابش کند و در هسته سقوط کند، و مدارهای پیوسته با طیف گسسته نمی‌خوانند؛ مکانیک کوانتومی آن را با اوربیتال‌های احتمالاتی جایگزین کرد. درس این مثال «تعمیم بدون شرایط مرزی» است، نه «شباهت سطحی» (ر.ک. تکنیک‌های ۶ و ۱۹). همچنین اصلی که PDF از یک مورد («اتحاد X و Y») استخراج می‌کند، فرضیه است نه قاعده؛ دست‌کم مورد دوم از دامنه‌ای دیگر لازم است.",
  ws: [
    { k: "case1", t: "area", l: "مورد اول: چه اتفاقی افتاد و چرا؟ با جزئیات ملموس.", rows: 4, req: true },
    { k: "case2", t: "area", l: "مورد دوم از دامنه‌ای متفاوت که به نظر ساختار مشابهی دارد", rows: 4, req: true },
    { k: "mapping", t: "table", l: "کدام عنصر در مورد اول همان نقشی را دارد که کدام عنصر در مورد دوم؟", cols: [ { k: "a", l: "در مورد اول", t: "text" }, { k: "b", l: "در مورد دوم", t: "text" }, { k: "role", l: "نقش یا رابطه مشترک", t: "text" } ], min: 3, req: true },
    { k: "principle", t: "area", l: "اصل مشترک — بدون هیچ اسم خاص، به شکل رابطه علّی میان متغیرها", h: "وقتی ... باشد، ... باعث ... می‌شود", rows: 3, req: true },
    { k: "ladder", t: "chain", l: "نردبان انتزاع: اصل کلی‌تر پشت این چیست؟", h: "جایی بایستید که اصل هنوز پیش‌بینی مشخص بدهد", n: 3, prefix: "یک پله بالاتر" },
    { k: "bounds", t: "area", l: "این اصل در چه شرایطی برقرار است و کجا نه؟", rows: 3, req: true },
    { k: "counter", t: "area", l: "مثال نقض: کجا این اصل به نظر شکست می‌خورد، و این درباره اصل چه می‌گوید؟", rows: 3, req: true },
    { k: "third", t: "area", l: "اصل را در دامنه سوم به کار ببرید: چه پیش‌بینی مشخصی می‌دهد؟", rows: 3, req: true }
  ],
  card: { q: "چه اصل بی‌نامی میان «{case1}» و «{case2}» مشترک است و مرزهایش کجاست؟", a: "اصل: {principle} · مرزها: {bounds} · پیش‌بینی: {third}" },
  ai: "تو منتقد کاربرگ «انتزاع و تعمیم» هستی و نباید اصل را برای کاربر بنویسی. بررسی کن نگاشت روی روابط است نه ظاهر، اصل واقعاً بی‌نام و علّی است، ارتفاع انتزاع هنوز پیش‌بینی می‌دهد و مثال نقض جدی گرفته شده؛ ضعیف‌ترین گام را نشان بده. دو یا سه پرسش بپرس (مثلاً «اگر اسم‌ها را حذف کنی، آیا اصل هنوز چیزی را رد می‌کند؟») و یک راهنمایی بده."
